protocol TitleReading { var prefix: String { get } }
struct FixedTitle: TitleReading { let prefix: String }
struct ScreenTitle {
    let settings: any TitleReading
    func text() -> String { settings.prefix }
}
let first = ScreenTitle(settings: FixedTitle(prefix: "Крупный"))
let second = ScreenTitle(settings: FixedTitle(prefix: "Обычный"))
assert(first.text() == "Крупный")
assert(second.text() == "Обычный")

